import { readFile, writeFile } from "node:fs/promises";

// Embed both originals so the sidebar icon also works when loaded as a data URI.
const directory = new URL("../page/", import.meta.url);
const [light, dark] = await Promise.all([
  readFile(new URL("icon.png", directory)),
  readFile(new URL("icon-dark.png", directory)),
]);
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48">
  <!-- Generated by scripts/generate-icon.mjs from the original PNG logos. -->
  <style>
    .dark { display: none; }
    @media (prefers-color-scheme: dark) {
      .light { display: none; }
      .dark { display: inline; }
    }
  </style>
  <image class="light" width="48" height="48" href="data:image/png;base64,${light.toString("base64")}"/>
  <image class="dark" width="48" height="48" href="data:image/png;base64,${dark.toString("base64")}"/>
</svg>
`;
await writeFile(new URL("icon.svg", directory), svg);
console.log("Generated the theme-aware sidebar and launch icon from both original PNG logos.");
